#include <bits/stdc++.h>
using namespace std;

// ---------- begin Matrix ----------
template <class R>
struct SemiRing {
    static R zero();
    static R one();
};

template <class R>
struct SquareMatrix {
    size_t size;
    vector<R> buf;

    SquareMatrix() {}
    SquareMatrix(size_t n) : size(n), buf(n * n) {}

    static SquareMatrix<R> zero(size_t n) {
        SquareMatrix<R> m(n);
        for (size_t i = 0; i < n * n; i++) m.buf[i] = SemiRing<R>::zero();
        return m;
    }

    static SquareMatrix<R> identity(size_t n) {
        SquareMatrix<R> e = zero(n);
        for (size_t i = 0; i < n; i++) {
            e.buf[i * n + i] = SemiRing<R>::one();
        }
        return e;
    }

    const R& get(size_t x, size_t y) const {
        return buf[x * size + y];
    }

    R& get_mut(size_t x, size_t y) {
        return buf[x * size + y];
    }

    SquareMatrix<R> matadd(const SquareMatrix<R>& rhs) const {
        SquareMatrix<R> res(size);
        for (size_t i = 0; i < size * size; i++) {
            res.buf[i] = buf[i] + rhs.buf[i];
        }
        return res;
    }

    SquareMatrix<R> matsub(const SquareMatrix<R>& rhs) const {
        SquareMatrix<R> res(size);
        for (size_t i = 0; i < size * size; i++) {
            res.buf[i] = buf[i] - rhs.buf[i];
        }
        return res;
    }

    SquareMatrix<R> matmul(const SquareMatrix<R>& rhs) const {
        size_t n = size;
        SquareMatrix<R> res = zero(n);
        for (size_t i = 0; i < n; i++) {
            for (size_t k = 0; k < n; k++) {
                R a = buf[i * n + k];
                for (size_t j = 0; j < n; j++) {
                    res.buf[i * n + j] = res.buf[i * n + j] + a * rhs.buf[k * n + j];
                }
            }
        }
        return res;
    }

    SquareMatrix<R> mat_pow(size_t n) const {
        size_t sz = size;
        SquareMatrix<R> t = identity(sz);
        SquareMatrix<R> s = *this;
        while (n > 0) {
            if (n & 1) {
                t = t.matmul(s);
            }
            s = s.matmul(s);
            n >>= 1;
        }
        return t;
    }
};
// ---------- end Matrix ----------

// ---------- begin ModInt ----------
struct Mod {
    static const uint32_t MOD = 1000000007u;
};

template <class T>
struct ModInt {
    uint32_t v;

    ModInt() : v(0) {}
    ModInt(uint32_t _v) : v(_v % T::MOD) {}
    static ModInt new_unchecked(uint32_t _v) { ModInt x; x.v = _v; return x; }
    static ModInt zero() { return new_unchecked(0); }
    static ModInt one() { return new_unchecked(1); }
    bool is_zero() const { return v == 0; }

    ModInt operator+(const ModInt& rhs) const {
        uint32_t d = v + rhs.v;
        if (d >= T::MOD) d -= T::MOD;
        return new_unchecked(d);
    }
    ModInt& operator+=(const ModInt& rhs) {
        *this = *this + rhs;
        return *this;
    }
    ModInt operator-(const ModInt& rhs) const {
        uint32_t d = T::MOD + v - rhs.v;
        if (d >= T::MOD) d -= T::MOD;
        return new_unchecked(d);
    }
    ModInt& operator-=(const ModInt& rhs) {
        *this = *this - rhs;
        return *this;
    }
    ModInt operator*(const ModInt& rhs) const {
        uint64_t x = (uint64_t)v * rhs.v % T::MOD;
        return new_unchecked((uint32_t)x);
    }
    ModInt& operator*=(const ModInt& rhs) {
        *this = *this * rhs;
        return *this;
    }
    ModInt operator-() const {
        if (v == 0) return zero();
        return new_unchecked(T::MOD - v);
    }

    ModInt pow(uint64_t n) const {
        ModInt t = one();
        ModInt s = *this;
        while (n > 0) {
            if (n & 1) t *= s;
            s *= s;
            n >>= 1;
        }
        return t;
    }

    ModInt inv() const {
        return pow((uint64_t)T::MOD - 2);
    }
};

template <>
struct SemiRing<ModInt<Mod>> {
    static ModInt<Mod> zero() { return ModInt<Mod>::zero(); }
    static ModInt<Mod> one() { return ModInt<Mod>::one(); }
};
// ---------- end ModInt ----------

// ---------- begin Precalc ----------
template <class T>
struct Precalc {
    vector<ModInt<T>> inv;
    vector<ModInt<T>> fact;
    vector<ModInt<T>> ifact;

    Precalc(size_t n) {
        inv.assign(n + 1, ModInt<T>::one());
        fact.assign(n + 1, ModInt<T>::one());
        ifact.assign(n + 1, ModInt<T>::one());
        for (size_t i = 2; i <= n; i++) {
            fact[i] = fact[i - 1] * ModInt<T>::new_unchecked((uint32_t)i);
        }
        ifact[n] = fact[n].inv();
        if (n > 0) {
            inv[n] = ifact[n] * fact[n - 1];
        }
        for (size_t i = n - 1; i >= 1; i--) {
            ifact[i] = ifact[i + 1] * ModInt<T>::new_unchecked((uint32_t)(i + 1));
            inv[i] = ifact[i] * fact[i - 1];
            if (i == 1) break;
        }
    }

    ModInt<T> invv(size_t n_) const {
        return inv[n_];
    }
    ModInt<T> factv(size_t n_) const {
        return fact[n_];
    }
    ModInt<T> ifactv(size_t n_) const {
        return ifact[n_];
    }
    ModInt<T> perm(size_t n_, size_t k) const {
        if (k > n_) return ModInt<T>::zero();
        return fact[n_] * ifact[n_ - k];
    }
    ModInt<T> comb(size_t n_, size_t k) const {
        if (k > n_) return ModInt<T>::zero();
        return fact[n_] * ifact[k] * ifact[n_ - k];
    }
};
// ---------- end Precalc ----------

