using Mat = SquareMatrix<M>;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<size_t> w(7);
    for (int i = 0; i < 7; i++) cin >> w[i];

    vector<Mat> mat;
    for (int i = 1; i <= 7; i++) {
        Mat m = Mat::zero(1u << i);
        for (int j = 0; j < (1 << i); j++) {
            for (int k = 0; k < (1 << (2 * i - 1)); k++) {
                if (j & k) continue;
                int next = 0;
                for (int x = 0; x < i; x++) {
                    bool left = (x == 0) || ((k >> (i + x - 1)) & 1);
                    bool down = (k >> x) & 1;
                    bool right = (x == i - 1) || ((k >> (i + x)) & 1);
                    if (left && down && right) {
                        next |= 1 << x;
                    }
                }
                m.get_mut(next, j) = m.get(next, j) + M::one();
            }
        }
        mat.push_back(m);
        Mat m2 = Mat::zero(1u << i);
        for (int j = 0; j < (1 << i); j++) {
            m2.get_mut(j, j) = M::one();
        }
        mat.push_back(m2);
    }

    auto mul = [](const Mat& m, const vector<M>& b) -> vector<M> {
        vector<M> res(b.size(), M::zero());
        for (size_t i = 0; i < b.size(); i++) {
            for (size_t j = 0; j < b.size(); j++) {
                res[i] += m.get(i, j) * b[j];
            }
        }
        return res;
    };

    vector<M> b(1u << 7, M::zero());
    bool ini = false;
    for (int idx = 6; idx >= 0; idx--) {
        size_t& wi = w[idx];
        Mat* mats = &mat[2 * idx];
        if (!ini && wi > 0) {
            wi--;
            ini = true;
            int i = idx + 1;
            for (int k = 0; k < (1 << (i - 1)); k++) {
                int bit = 0;
                for (int x = 0; x < i; x++) {
                    bool left = (x == 0) || ((k >> (x - 1)) & 1);
                    bool down = true;
                    bool right = (x == i - 1) || ((k >> x) & 1);
                    if (left && right && down) {
                        bit |= 1 << x;
                    }
                }
                b[bit] += M::one();
            }
        }
        b = mul(mats[1], b);
        Mat powm = mats[0].mat_pow(wi);
        b = mul(powm, b);
        b.resize(1u << (idx + 1));
    }

    M ans = b[0];
    cout << ans.v << '\n';
    return 0;
}

