    return os << m.v;
}

uint64_t mod_pow_u64(uint64_t r, uint64_t n, uint64_t m) {
    uint64_t t = 1 % m;
    uint64_t s = r % m;
    while (n > 0) {
        if (n & 1) t = t * s % m;
        s = s * s % m;
        n >>= 1;
    }
    return t;
}
