template <class T>
struct ModInt {
    uint32_t v;
    ModInt() : v(0) {}
    ModInt(uint32_t _v) { v = _v % T::MOD; }
    static ModInt new_unchecked(uint32_t _v) {
        ModInt x;
        x.v = _v;
        return x;
    }
    static ModInt zero() { return new_unchecked(0); }
    static ModInt one() { return new_unchecked(1); }
    bool is_zero() const { return v == 0; }

    ModInt(const ModInt &o) = default;
    ModInt &operator=(const ModInt &o) = default;

    ModInt operator+(const ModInt &rhs) const {
        uint32_t d = v + rhs.v;
        if (d >= T::MOD) d -= T::MOD;
        return new_unchecked(d);
    }
    ModInt &operator+=(const ModInt &rhs) {
        *this = *this + rhs;
        return *this;
    }
    ModInt operator-(const ModInt &rhs) const {
        uint32_t d = T::MOD + v - rhs.v;
        if (d >= T::MOD) d -= T::MOD;
        return new_unchecked(d);
    }
    ModInt &operator-=(const ModInt &rhs) {
        *this = *this - rhs;
        return *this;
    }
    ModInt operator*(const ModInt &rhs) const {
        uint64_t r = (uint64_t)v * rhs.v % (uint64_t)T::MOD;
        return new_unchecked((uint32_t)r);
    }
    ModInt &operator*=(const ModInt &rhs) {
        *this = *this * rhs;
        return *this;
    }
    ModInt operator-() const {
        if (v == 0) return zero();
        return new_unchecked(T::MOD - v);
    }
    ModInt pow(uint64_t n) const {
        ModInt t = one();
        ModInt s = *this;
        while (n > 0) {
            if (n & 1) t *= s;
            s *= s;
            n >>= 1;
        }
        return t;
    }
    ModInt inv() const {
        assert(v != 0);
        return pow((uint64_t)T::MOD - 2);
    }
};

