template <class R>
struct SquareMatrix {
    size_t size;
    vector<R> buf;
    SquareMatrix() : size(0) {}
    SquareMatrix(size_t n) : size(n), buf(n * n) {}

    static SquareMatrix zero(size_t n) {
        SquareMatrix m(n);
        for (size_t i = 0; i < n * n; i++) m.buf[i] = R::zero();
        return m;
    }
    static SquareMatrix identity(size_t n) {
        SquareMatrix m = zero(n);
        for (size_t i = 0; i < n; i++) m.buf[i * n + i] = R::one();
        return m;
    }
    const R &get(size_t x, size_t y) const {
        assert(x < size && y < size);
        return buf[x * size + y];
    }
    R &get_mut(size_t x, size_t y) {
        assert(x < size && y < size);
        return buf[x * size + y];
    }
    SquareMatrix matadd(const SquareMatrix &rhs) const {
        assert(size == rhs.size);
        SquareMatrix res(size);
        res.buf.resize(size * size);
        for (size_t i = 0; i < size * size; i++) {
            res.buf[i] = buf[i] + rhs.buf[i];
        }
        return res;
    }
    SquareMatrix matsub(const SquareMatrix &rhs) const {
        assert(size == rhs.size);
        SquareMatrix res(size);
        res.buf.resize(size * size);
        for (size_t i = 0; i < size * size; i++) {
            res.buf[i] = buf[i] - rhs.buf[i];
        }
        return res;
    }
    SquareMatrix matmul(const SquareMatrix &rhs) const {
        size_t n = size;
        assert(n == rhs.size);
        SquareMatrix res = zero(n);
        for (size_t i = 0; i < n; i++) {
            for (size_t k = 0; k < n; k++) {
                R a = buf[i * n + k];
                for (size_t j = 0; j < n; j++) {
                    res.buf[i * n + j] = res.buf[i * n + j] + a * rhs.buf[k * n + j];
                }
            }
        }
        return res;
    }
    SquareMatrix mat_pow(size_t n) const {
        size_t sz = size;
        SquareMatrix t = identity(sz);
        SquareMatrix s = *this;
        while (n > 0) {
            if (n & 1) t = t.matmul(s);
            s = s.matmul(s);
            n >>= 1;
        }
        return t;
    }
};

