struct StaticMod {
    static uint32_t STATIC_MOD;
    static uint32_t modulo() { return STATIC_MOD; }
    static void set_modulo(uint32_t p) { STATIC_MOD = p; }
};
uint32_t StaticMod::STATIC_MOD = 0;

template <class T>
struct ModuloTrait {
    static uint32_t modulo() { return T::MOD; }
};

template <>
struct ModuloTrait<StaticMod> {
    static uint32_t modulo() { return StaticMod::modulo(); }
};

template <class T>
struct ModInt {
    uint32_t v;
    ModInt() : v(0) {}
    ModInt(uint32_t _v) { v = _v % ModuloTrait<T>::modulo(); }
    static ModInt new_unchecked(uint32_t d) {
        ModInt x;
        x.v = d;
        return x;
    }
    static ModInt zero() { return new_unchecked(0); }
    static ModInt one() { return new_unchecked(1); }
    bool is_zero() const { return v == 0; }
    ModInt pow(uint64_t n) const {
        ModInt t = one();
        ModInt s = *this;
        while (n > 0) {
            if (n & 1) t *= s;
            s *= s;
            n >>= 1;
        }
        return t;
    }
    ModInt inv() const {
        return pow(ModuloTrait<T>::modulo() - 2);
    }
    ModInt& operator+=(const ModInt& rhs) {
        uint32_t d = v + rhs.v;
        uint32_t m = ModuloTrait<T>::modulo();
        if (d >= m) d -= m;
        v = d;
        return *this;
    }
    ModInt& operator-=(const ModInt& rhs) {
        uint32_t m = ModuloTrait<T>::modulo();
        uint32_t d = m + v - rhs.v;
        if (d >= m) d -= m;
        v = d;
        return *this;
    }
    ModInt& operator*=(const ModInt& rhs) {
        uint64_t r = (uint64_t)v * rhs.v % ModuloTrait<T>::modulo();
        v = (uint32_t)r;
        return *this;
    }
    ModInt operator+(const ModInt& rhs) const {
        ModInt res = *this;
        res += rhs;
        return res;
    }
    ModInt operator-(const ModInt& rhs) const {
        ModInt res = *this;
        res -= rhs;
        return res;
    }
    ModInt operator*(const ModInt& rhs) const {
        ModInt res = *this;
        res *= rhs;
        return res;
    }
    ModInt operator-() const {
        if (v == 0) return zero();
        return new_unchecked(ModuloTrait<T>::modulo() - v);
    }
};

